pub fn parse_for(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<ExprResult> {
    {
        let span = token_span(token_stream_first(tokens.clone()));
        let dummy_expr = parse_recovery_placeholder();
        let r = expect(
            tokens.clone(),
            Rc::new(ExpectedToken::ExpectKeyword {
                text: "for".to_string(),
            }),
        );
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: ctx.clone(),
                err: r.err.clone(),
            });
        }
        let r = expect_name(r.tokens.clone());
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: ctx.clone(),
                err: r.err.clone(),
            });
        }
        let var_name = r.name.clone();
        let var_name_span = r.span.clone();
        let r = expect(
            r.tokens.clone(),
            Rc::new(ExpectedToken::ExpectKeyword {
                text: "in".to_string(),
            }),
        );
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: ctx.clone(),
                err: r.err.clone(),
            });
        }
        let r = parse_expr_no_brace(r.tokens.clone(), ctx.clone());
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: r.expr.clone(),
                tokens: r.tokens.clone(),
                ctx: r.ctx.clone(),
                err: r.err.clone(),
            });
        }
        let collection = (*r.expr).clone();
        let r = parse_block(skip_newlines(r.tokens.clone()), r.ctx.clone());
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: r.expr.clone(),
                tokens: r.tokens.clone(),
                ctx: r.ctx.clone(),
                err: r.err.clone(),
            });
        }
        let body = (*r.expr).clone();
        let for_expr = make_named_expr_node(
            var_name,
            Rc::new(ExprData::ExprForEach),
            Rc::new(vec![Rc::new(collection), Rc::new(body)]),
            None,
            span,
            var_name_span,
        );
        Rc::new(ExprResult {
            expr: for_expr,
            tokens: r.tokens.clone(),
            ctx: r.ctx.clone(),
            err: None,
        })
    }
}

pub fn parse_record_literal(
    tokens: Rc<TokenStream>,
    ctx: Rc<ParseContext>,
    name: String,
    span: Rc<SourceSpan>,
) -> Rc<ExprResult> {
    {
        let dummy_expr = parse_recovery_placeholder();
        let r = expect(tokens.clone(), Rc::new(ExpectedToken::ExpectLBrace));
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: ctx.clone(),
                err: r.err.clone(),
            });
        }
        let tokens = skip_newlines(r.tokens.clone());
        let r = parse_field_init_list(tokens.clone(), ctx.clone());
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: r.ctx.clone(),
                err: r.err.clone(),
            });
        }
        let tokens = skip_newlines(r.tokens.clone());
        let r2 = expect(tokens.clone(), Rc::new(ExpectedToken::ExpectRBrace));
        if has_err(r2.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r2.tokens.clone(),
                ctx: r.ctx.clone(),
                err: r2.err.clone(),
            });
        }
        Rc::new(ExprResult {
            expr: make_named_expr_node(
                name,
                Rc::new(ExprData::ExprRecordLit { parent_enum: None }),
                r.fields.clone(),
                None,
                span.clone(),
                span.clone(),
            ),
            tokens: r2.tokens.clone(),
            ctx: r.ctx.clone(),
            err: None,
        })
    }
}

pub fn parse_field_init_list(
    tokens: Rc<TokenStream>,
    ctx: Rc<ParseContext>,
) -> Rc<FieldInitsResult> {
    parse_field_init_list_acc(tokens, ctx, Rc::new(vec![]))
}

pub fn parse_field_init_list_acc(
    mut tokens: Rc<TokenStream>,
    mut ctx: Rc<ParseContext>,
    mut acc: Rc<Vec<Rc<Node>>>,
) -> Rc<FieldInitsResult> {
    loop {
        tokens = skip_newlines(tokens.clone());
        if (tok_is_rbrace(token_stream_first(tokens.clone()))
            || tok_is_eof(token_stream_first(tokens.clone())))
        {
            break Rc::new(FieldInitsResult {
                fields: acc,
                tokens: tokens.clone(),
                ctx: ctx,
                err: None,
            });
        } else {
            let r = parse_field_init(tokens.clone(), ctx);
            if has_err(r.err.clone()) {
                return Rc::new(FieldInitsResult {
                    fields: Rc::new(vec![]),
                    tokens: r.tokens.clone(),
                    ctx: r.ctx.clone(),
                    err: r.err.clone(),
                });
            }
            let e = eat(r.tokens.clone(), Rc::new(ExpectedToken::ExpectComma));
            tokens = skip_newlines(match (*e).clone() {
                EatResult::EatConsumed { tokens: __ec, .. } => __ec.clone(),
                EatResult::EatUnchanged { tokens: _, .. } => r.tokens.clone(),
            });
            {
                let __tco_0 = r.ctx.clone();
                let __tco_1 = v1_rt::rc_list_push(acc, r.field.clone());
                ctx = __tco_0;
                acc = __tco_1;
                continue;
            }
        }
    }
}

pub fn parse_field_init(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<FieldInitResult> {
    {
        let zero_span = make_span(0, 0);
        let span = token_span(token_stream_first(tokens.clone()));
        let dummy_fi = make_field_init_node(
            "".to_string(),
            parse_recovery_placeholder(),
            zero_span.clone(),
            zero_span.clone(),
        );
        let tok = token_stream_first(tokens.clone());
        if (tok_is_ident(tok.clone()) || tok_is_keyword_name(tok.clone())) {
            {
                let name_r = expect_name(tokens.clone());
                if has_err(name_r.err.clone()) {
                    return Rc::new(FieldInitResult {
                        field: dummy_fi.clone(),
                        tokens: name_r.tokens.clone(),
                        ctx: ctx.clone(),
                        err: name_r.err.clone(),
                    });
                }
                let n = name_r.name.clone();
                if tok_is_colon(token_stream_first(name_r.tokens.clone())) {
                    {
                        let r =
                            parse_expr(token_stream_advance(name_r.tokens.clone(), 1), ctx.clone());
                        if has_err(r.err.clone()) {
                            return Rc::new(FieldInitResult {
                                field: dummy_fi.clone(),
                                tokens: r.tokens.clone(),
                                ctx: r.ctx.clone(),
                                err: r.err.clone(),
                            });
                        }
                        let fi = make_field_init_node(
                            n.clone(),
                            r.expr.clone(),
                            span.clone(),
                            name_r.span.clone(),
                        );
                        Rc::new(FieldInitResult {
                            field: fi,
                            tokens: r.tokens.clone(),
                            ctx: r.ctx.clone(),
                            err: None,
                        })
                    }
                } else {
                    {
                        let fi = make_field_init_node(
                            n.clone(),
                            make_named_expr_node(
                                n.clone(),
                                Rc::new(ExprData::ExprVar { binding_kind: None }),
                                Rc::new(vec![]),
                                None,
                                span.clone(),
                                name_r.span.clone(),
                            ),
                            span.clone(),
                            name_r.span.clone(),
                        );
                        Rc::new(FieldInitResult {
                            field: fi,
                            tokens: name_r.tokens.clone(),
                            ctx: ctx.clone(),
                            err: None,
                        })
                    }
                }
            }
        } else {
            if (tok_is_lit_str(tok.clone()) && peek_is_colon_after_ident(tokens.clone())) {
                {
                    let str_name = match tok.clone() {
                        Some(t) => t.text.clone(),
                        None => "_".to_string(),
                    };
                    let r = parse_expr(token_stream_advance(tokens.clone(), 2), ctx.clone());
                    if has_err(r.err.clone()) {
                        return Rc::new(FieldInitResult {
                            field: dummy_fi.clone(),
                            tokens: r.tokens.clone(),
                            ctx: r.ctx.clone(),
                            err: r.err.clone(),
                        });
                    }
                    let fi =
                        make_field_init_node(str_name, r.expr.clone(), span.clone(), no_span());
                    Rc::new(FieldInitResult {
                        field: fi,
                        tokens: r.tokens.clone(),
                        ctx: r.ctx.clone(),
                        err: None,
                    })
                }
            } else {
                {
                    let r = parse_expr(tokens.clone(), ctx.clone());
                    if has_err(r.err.clone()) {
                        return Rc::new(FieldInitResult {
                            field: dummy_fi.clone(),
                            tokens: r.tokens.clone(),
                            ctx: r.ctx.clone(),
                            err: r.err.clone(),
                        });
                    }
                    let fi = make_field_init_node(
                        "_".to_string(),
                        r.expr.clone(),
                        span.clone(),
                        no_span(),
                    );
                    Rc::new(FieldInitResult {
                        field: fi,
                        tokens: r.tokens.clone(),
                        ctx: r.ctx.clone(),
                        err: None,
                    })
                }
            }
        }
    }
}

pub fn parse_list_literal(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<ExprResult> {
    {
        let span = token_span(token_stream_first(tokens.clone()));
        let dummy_expr = parse_recovery_placeholder();
        let r = expect(tokens.clone(), Rc::new(ExpectedToken::ExpectLBracket));
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: ctx.clone(),
                err: r.err.clone(),
            });
        }
        let r = parse_expr_list_until(
            skip_newlines(r.tokens.clone()),
            ctx.clone(),
            Rc::new(ExpectedToken::ExpectRBracket),
        );
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: r.ctx.clone(),
                err: r.err.clone(),
            });
        }
        let r2 = expect(
            skip_newlines(r.tokens.clone()),
            Rc::new(ExpectedToken::ExpectRBracket),
        );
        if has_err(r2.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r2.tokens.clone(),
                ctx: r.ctx.clone(),
                err: r2.err.clone(),
            });
        }
        Rc::new(ExprResult {
            expr: make_expr_node(Rc::new(ExprData::ExprListLit), r.exprs.clone(), None, span),
            tokens: r2.tokens.clone(),
            ctx: r.ctx.clone(),
            err: None,
        })
    }
}

pub fn parse_expr_list_until(
    tokens: Rc<TokenStream>,
    ctx: Rc<ParseContext>,
    end_expected: Rc<ExpectedToken>,
) -> Rc<ExprsResult> {
    parse_expr_list_until_acc(tokens, ctx, end_expected, Rc::new(vec![]))
}

pub fn parse_expr_list_until_acc(
    mut tokens: Rc<TokenStream>,
    mut ctx: Rc<ParseContext>,
    mut end_expected: Rc<ExpectedToken>,
    mut acc: Rc<Vec<Rc<Node>>>,
) -> Rc<ExprsResult> {
    loop {
        tokens = skip_newlines(tokens.clone());
        let at_end_tag = match token_stream_first(tokens.clone()) {
            Some(t) => token_matches_expected(t.clone(), end_expected.clone()),
            None => false,
        };
        if (at_end_tag || tok_is_eof(token_stream_first(tokens.clone()))) {
            break Rc::new(ExprsResult {
                exprs: acc,
                tokens: tokens.clone(),
                ctx: ctx,
                err: None,
            });
        } else {
            let r = parse_expr(tokens.clone(), ctx);
            if has_err(r.err.clone()) {
                return Rc::new(ExprsResult {
                    exprs: Rc::new(vec![]),
                    tokens: r.tokens.clone(),
                    ctx: r.ctx.clone(),
                    err: r.err.clone(),
                });
            }
            let e = eat(r.tokens.clone(), Rc::new(ExpectedToken::ExpectComma));
            tokens = skip_newlines(match (*e).clone() {
                EatResult::EatConsumed { tokens: __ec, .. } => __ec.clone(),
                EatResult::EatUnchanged { tokens: _, .. } => r.tokens.clone(),
            });
            {
                let __tco_0 = r.ctx.clone();
                let __tco_1 = v1_rt::rc_list_push(acc, r.expr.clone());
                ctx = __tco_0;
                acc = __tco_1;
                continue;
            }
        }
    }
}

pub fn parse_paren_expr(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<ExprResult> {
    {
        let span = token_span(token_stream_first(tokens.clone()));
        let dummy_expr = parse_recovery_placeholder();
        let r = expect(tokens.clone(), Rc::new(ExpectedToken::ExpectLParen));
        if has_err(r.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy_expr.clone(),
                tokens: r.tokens.clone(),
                ctx: ctx.clone(),
                err: r.err.clone(),
            });
        }
        let tokens = skip_newlines(r.tokens.clone());
        if tok_is_rparen(token_stream_first(tokens.clone())) {
            Rc::new(ExprResult {
                expr: make_expr_node(
                    Rc::new(ExprData::ExprRecordLit { parent_enum: None }),
                    Rc::new(vec![]),
                    None,
                    span,
                ),
                tokens: token_stream_advance(tokens.clone(), 1),
                ctx: ctx.clone(),
                err: None,
            })
        } else {
            {
                let lambda_r = try_lambda_params(tokens.clone(), ctx.clone());
                if lambda_r.is_lambda.clone() {
                    {
                        let r = parse_lambda_body(lambda_r.tokens.clone(), lambda_r.ctx.clone());
                        if has_err(r.err.clone()) {
                            return Rc::new(ExprResult {
                                expr: r.expr.clone(),
                                tokens: r.tokens.clone(),
                                ctx: r.ctx.clone(),
                                err: r.err.clone(),
                            });
                        }
                        Rc::new(ExprResult {
                            expr: make_expr_node(
                                Rc::new(ExprData::ExprLambda),
                                v1_rt::concat(
                                    Rc::new(vec![r.expr.clone()]),
                                    Rc::new({
                                        let mut __result = Vec::new();
                                        for p in lambda_r.params.clone().iter().cloned() {
                                            __result.push(parsed_name_leaf(
                                                p.name.clone(),
                                                p.span.clone(),
                                            ));
                                        }
                                        __result
                                    }),
                                ),
                                None,
                                span,
                            ),
                            tokens: r.tokens.clone(),
                            ctx: r.ctx.clone(),
                            err: None,
                        })
                    }
                } else {
                    {
                        let r = parse_expr(lambda_r.tokens.clone(), lambda_r.ctx.clone());
                        if has_err(r.err.clone()) {
                            return Rc::new(ExprResult {
                                expr: r.expr.clone(),
                                tokens: r.tokens.clone(),
                                ctx: r.ctx.clone(),
                                err: r.err.clone(),
                            });
                        }
                        let tokens = skip_newlines(r.tokens.clone());
                        let r2 = expect(tokens.clone(), Rc::new(ExpectedToken::ExpectRParen));
                        if has_err(r2.err.clone()) {
                            return Rc::new(ExprResult {
                                expr: dummy_expr.clone(),
                                tokens: r2.tokens.clone(),
                                ctx: r.ctx.clone(),
                                err: r2.err.clone(),
                            });
                        }
                        Rc::new(ExprResult {
                            expr: r.expr.clone(),
                            tokens: r2.tokens.clone(),
                            ctx: r.ctx.clone(),
                            err: None,
                        })
                    }
                }
            }
        }
    }
}

pub fn parse_fn_lambda(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<ExprResult> {
    {
        let span = token_span(token_stream_first(tokens.clone()));
        let dummy = parse_recovery_placeholder();
        let r1 = expect(
            tokens.clone(),
            Rc::new(ExpectedToken::ExpectKeyword {
                text: "fn".to_string(),
            }),
        );
        if has_err(r1.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy.clone(),
                tokens: r1.tokens.clone(),
                ctx: ctx.clone(),
                err: r1.err.clone(),
            });
        }
        let r2 = expect(r1.tokens.clone(), Rc::new(ExpectedToken::ExpectLParen));
        if has_err(r2.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy.clone(),
                tokens: r2.tokens.clone(),
                ctx: ctx.clone(),
                err: r2.err.clone(),
            });
        }
        let params_r = collect_fn_lambda_params(r2.tokens.clone(), ctx.clone(), Rc::new(vec![]));
        let r3 = expect(
            params_r.tokens.clone(),
            Rc::new(ExpectedToken::ExpectRParen),
        );
        if has_err(r3.err.clone()) {
            return Rc::new(ExprResult {
                expr: dummy.clone(),
                tokens: r3.tokens.clone(),
                ctx: params_r.ctx.clone(),
                err: r3.err.clone(),
            });
        }
        let tokens = skip_newlines(r3.tokens.clone());
        let body_r = parse_brace_expr(tokens.clone(), params_r.ctx.clone());
        if has_err(body_r.err.clone()) {
            return body_r.clone();
        }
        Rc::new(ExprResult {
            expr: make_expr_node(
                Rc::new(ExprData::ExprLambda),
                v1_rt::concat(
                    Rc::new(vec![body_r.expr.clone()]),
                    Rc::new({
                        let mut __result = Vec::new();
                        for p in params_r.params.clone().iter().cloned() {
                            __result.push(parsed_name_leaf(p.name.clone(), p.span.clone()));
                        }
                        __result
                    }),
                ),
                None,
                span,
            ),
            tokens: body_r.tokens.clone(),
            ctx: body_r.ctx.clone(),
            err: None,
        })
    }
}

pub fn collect_fn_lambda_params(
    mut tokens: Rc<TokenStream>,
    mut ctx: Rc<ParseContext>,
    mut acc: Rc<Vec<Rc<ParserParam>>>,
) -> Rc<IdentCollectResult> {
    loop {
        tokens = skip_newlines(tokens.clone());
        if tok_is_rparen(token_stream_first(tokens.clone())) {
            break Rc::new(IdentCollectResult {
                success: true,
                params: acc,
                tokens: tokens.clone(),
                ctx: ctx,
                err: None,
            });
        } else {
            let name_r = expect_ident(tokens.clone());
            if has_err(name_r.err.clone()) {
                break Rc::new(IdentCollectResult {
                    success: false,
                    params: acc,
                    tokens: name_r.tokens.clone(),
                    ctx: ctx,
                    err: name_r.err.clone(),
                });
            } else {
                tokens = skip_newlines(name_r.tokens.clone());
                if tok_is_comma(token_stream_first(tokens.clone())) {
                    {
                        let __tco_0 = token_stream_advance(tokens, 1);
                        let __tco_1 = v1_rt::rc_list_push(
                            acc,
                            Rc::new(ParserParam {
                                name: name_r.name.clone(),
                                span: name_r.span.clone(),
                            }),
                        );
                        tokens = __tco_0;
                        acc = __tco_1;
                        continue;
                    }
                } else {
                    break Rc::new(IdentCollectResult {
                        success: true,
                        params: v1_rt::rc_list_push(
                            acc,
                            Rc::new(ParserParam {
                                name: name_r.name.clone(),
                                span: name_r.span.clone(),
                            }),
                        ),
                        tokens: tokens.clone(),
                        ctx: ctx,
                        err: None,
                    });
                }
            }
        }
    }
}

pub fn try_lambda_params(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<LambdaCheckResult> {
    {
        let r = collect_lambda_idents(tokens.clone(), ctx.clone(), Rc::new(vec![]));
        if (r.success.clone() && ((r.params.clone().len() as i64) >= 2)) {
            if tok_is_rparen(token_stream_first(r.tokens.clone())) {
                {
                    let after_rparen = token_stream_advance(r.tokens.clone(), 1);
                    if tok_is_fat_arrow(token_stream_first(after_rparen.clone())) {
                        Rc::new(LambdaCheckResult {
                            is_lambda: true,
                            params: r.params.clone(),
                            tokens: token_stream_advance(after_rparen.clone(), 1),
                            ctx: r.ctx.clone(),
                            err: None,
                        })
                    } else {
                        Rc::new(LambdaCheckResult {
                            is_lambda: false,
                            params: Rc::new(vec![]),
                            tokens: tokens.clone(),
                            ctx: ctx.clone(),
                            err: None,
                        })
                    }
                }
            } else {
                Rc::new(LambdaCheckResult {
                    is_lambda: false,
                    params: Rc::new(vec![]),
                    tokens: tokens.clone(),
                    ctx: ctx.clone(),
                    err: None,
                })
            }
        } else {
            Rc::new(LambdaCheckResult {
                is_lambda: false,
                params: Rc::new(vec![]),
                tokens: tokens.clone(),
                ctx: ctx.clone(),
                err: None,
            })
        }
    }
}

pub fn collect_lambda_idents(
    mut tokens: Rc<TokenStream>,
    mut ctx: Rc<ParseContext>,
    mut acc: Rc<Vec<Rc<ParserParam>>>,
) -> Rc<IdentCollectResult> {
    loop {
        if tok_is_ident(token_stream_first(tokens.clone())) {
            let tok = token_stream_first(tokens.clone());
            let param = Rc::new(ParserParam {
                name: tok.clone().unwrap().text.clone(),
                span: tok.clone().unwrap().span.clone(),
            });
            let new_acc = v1_rt::rc_list_push(acc, param);
            match (*eat(
                token_stream_advance(tokens.clone(), 1),
                Rc::new(ExpectedToken::ExpectComma),
            ))
            .clone()
            {
                EatResult::EatConsumed { tokens: __ec, .. } => {
                    let __tco_0 = __ec.clone();
                    let __tco_1 = new_acc;
                    tokens = __tco_0;
                    acc = __tco_1;
                    continue;
                }
                EatResult::EatUnchanged { tokens: __eu, .. } => {
                    break Rc::new(IdentCollectResult {
                        success: true,
                        params: new_acc,
                        tokens: token_stream_advance(tokens.clone(), 1),
                        ctx: ctx,
                        err: None,
                    });
                }
            }
        } else {
            break Rc::new(IdentCollectResult {
                success: false,
                params: acc,
                tokens: tokens.clone(),
                ctx: ctx,
                err: None,
            });
        }
    }
}

pub fn parse_string_interp(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<ExprResult> {
    {
        let tok = token_stream_first(tokens.clone());
        let span = token_span(tok.clone());
        let sh = match tok.clone() {
            Some(t) => Some(t.shape.clone()),
            None => None,
        };
        match sh {
            Some(TokenShape::ShStrBegin) => {
                let prefix = tok.clone().unwrap().text.clone();
                let parts_init = if (v1_rt::string_length(&prefix) > 0) {
                    Rc::new(vec![Rc::new(StringPart::Text {
                        value: prefix.clone(),
                    })])
                } else {
                    Rc::new(vec![])
                };
                parse_interp_parts(
                    token_stream_advance(tokens.clone(), 1),
                    ctx,
                    parts_init,
                    span.clone(),
                )
            }
            _ => Rc::new(ExprResult {
                expr: parse_recovery_expr(
                    span.clone(),
                    "expected string interpolation".to_string(),
                ),
                tokens: tokens.clone(),
                ctx: ctx,
                err: Some(parse_error(
                    "expected string interpolation".to_string(),
                    span.clone(),
                )),
            }),
        }
    }
}

pub fn parse_interp_parts(
    mut tokens: Rc<TokenStream>,
    mut ctx: Rc<ParseContext>,
    mut parts: Rc<Vec<Rc<StringPart>>>,
    mut span: Rc<SourceSpan>,
) -> Rc<ExprResult> {
    loop {
        let r = parse_expr(tokens.clone(), ctx.clone());
        if has_err(r.err.clone()) {
            return r.clone();
        }
        let new_parts = v1_rt::rc_list_push(
            parts,
            Rc::new(StringPart::Interpolation {
                expr: r.expr.clone(),
            }),
        );
        tokens = r.tokens.clone();
        ctx = r.ctx.clone();
        let interp_tok = token_stream_first(tokens.clone());
        let interp_sh = match interp_tok.clone() {
            Some(t) => Some(t.shape.clone()),
            None => None,
        };
        match interp_sh {
            Some(TokenShape::ShStrMid) => {
                let mid = interp_tok.clone().unwrap().text.clone();
                let mid_parts = if (v1_rt::string_length(&mid) > 0) {
                    v1_rt::rc_list_push(new_parts, Rc::new(StringPart::Text { value: mid.clone() }))
                } else {
                    new_parts
                };
                {
                    let __tco_0 = token_stream_advance(tokens, 1);
                    let __tco_1 = mid_parts;
                    tokens = __tco_0;
                    parts = __tco_1;
                    continue;
                }
            }
            Some(TokenShape::ShStrEnd) => {
                let suffix = interp_tok.clone().unwrap().text.clone();
                let final_parts = if (v1_rt::string_length(&suffix) > 0) {
                    v1_rt::rc_list_push(
                        new_parts,
                        Rc::new(StringPart::Text {
                            value: suffix.clone(),
                        }),
                    )
                } else {
                    new_parts
                };
                break Rc::new(ExprResult {
                    expr: make_expr_node(
                        Rc::new(ExprData::ExprStringInterp),
                        Rc::new({
                            let mut __result = Vec::new();
                            for p in final_parts.iter().cloned() {
                                __result.push(match (*p.clone()).clone() {
                                    StringPart::Text { value: v, .. } => {
                                        make_text_part_node(v.clone(), span.clone())
                                    }
                                    StringPart::Interpolation { expr: e, .. } => {
                                        make_interp_part_node(e.clone(), span.clone())
                                    }
                                });
                            }
                            __result
                        }),
                        None,
                        span.clone(),
                    ),
                    tokens: token_stream_advance(tokens.clone(), 1),
                    ctx: ctx.clone(),
                    err: None,
                });
            }
            _ => {
                break Rc::new(ExprResult {
                    expr: make_expr_node(
                        Rc::new(ExprData::ExprStringInterp),
                        Rc::new({
                            let mut __result = Vec::new();
                            for p in new_parts.iter().cloned() {
                                __result.push(match (*p.clone()).clone() {
                                    StringPart::Text { value: v, .. } => {
                                        make_text_part_node(v.clone(), span.clone())
                                    }
                                    StringPart::Interpolation { expr: e, .. } => {
                                        make_interp_part_node(e.clone(), span.clone())
                                    }
                                });
                            }
                            __result
                        }),
                        None,
                        span.clone(),
                    ),
                    tokens: tokens.clone(),
                    ctx: ctx.clone(),
                    err: None,
                });
            }
        }
    }
}

pub fn parse_brace_expr(tokens: Rc<TokenStream>, ctx: Rc<ParseContext>) -> Rc<ExprResult> {
    {
        let span = token_span(token_stream_first(tokens.clone()));
        let dummy_expr = parse_recovery_placeholder();
        let tokens = skip_newlines(token_stream_advance(tokens.clone(), 1));
        let tok = token_stream_first(tokens.clone());
        if tok_is_rbrace(tok.clone()) {
            Rc::new(ExprResult {
                expr: make_expr_node(
                    Rc::new(ExprData::ExprRecordLit { parent_enum: None }),
                    Rc::new(vec![]),
                    None,
                    span,
                ),
                tokens: token_stream_advance(tokens.clone(), 1),
                ctx: ctx,
                err: None,
            })
        } else {
            {
                let sh = match tok.clone() {
                    Some(t) => Some(t.shape.clone()),
                    None => None,
                };
                match sh {
                    Some(TokenShape::ShKeyword) => {
                        let brace_kw = tok_keyword_text(tok.clone());
                        if ((brace_kw.clone() == "let".to_string())
                            || (brace_kw.clone() == "return".to_string()))
                        {
                            {
                                let r = parse_stmts(tokens.clone(), ctx);
                                if has_err(r.err.clone()) {
                                    return Rc::new(ExprResult {
                                        expr: dummy_expr.clone(),
                                        tokens: r.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: r.err.clone(),
                                    });
                                }
                                let tokens = skip_newlines(r.tokens.clone());
                                let r2 =
                                    expect(tokens.clone(), Rc::new(ExpectedToken::ExpectRBrace));
                                if has_err(r2.err.clone()) {
                                    return Rc::new(ExprResult {
                                        expr: dummy_expr.clone(),
                                        tokens: r2.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: r2.err.clone(),
                                    });
                                }
                                if ((r.stmts.clone().len() as i64) == 1) {
                                    Rc::new(ExprResult {
                                        expr: r.stmts.clone().first().cloned().clone().unwrap(),
                                        tokens: r2.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: None,
                                    })
                                } else {
                                    Rc::new(ExprResult {
                                        expr: make_expr_node(
                                            Rc::new(ExprData::ExprBlock),
                                            r.stmts.clone(),
                                            None,
                                            span,
                                        ),
                                        tokens: r2.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: None,
                                    })
                                }
                            }
                        } else {
                            if (tok_is_keyword_name(tok.clone())
                                && peek_is_colon_after_ident(tokens.clone()))
                            {
                                {
                                    let r = parse_field_init_list(tokens.clone(), ctx);
                                    if has_err(r.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r.err.clone(),
                                        });
                                    }
                                    let tokens = skip_newlines(r.tokens.clone());
                                    let r2 = expect(
                                        tokens.clone(),
                                        Rc::new(ExpectedToken::ExpectRBrace),
                                    );
                                    if has_err(r2.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r2.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r2.err.clone(),
                                        });
                                    }
                                    Rc::new(ExprResult {
                                        expr: make_expr_node(
                                            Rc::new(ExprData::ExprRecordLit { parent_enum: None }),
                                            r.fields.clone(),
                                            None,
                                            span,
                                        ),
                                        tokens: r2.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: None,
                                    })
                                }
                            } else {
                                {
                                    let r = parse_expr(tokens.clone(), ctx);
                                    if has_err(r.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r.err.clone(),
                                        });
                                    }
                                    let tokens = skip_newlines(r.tokens.clone());
                                    let r2 = expect(
                                        tokens.clone(),
                                        Rc::new(ExpectedToken::ExpectRBrace),
                                    );
                                    if has_err(r2.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r2.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r2.err.clone(),
                                        });
                                    }
                                    Rc::new(ExprResult {
                                        expr: r.expr.clone(),
                                        tokens: r2.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: None,
                                    })
                                }
                            }
                        }
                    }
                    _ => {
                        let ident_or_keyword =
                            (tok_is_ident(tok.clone()) || tok_is_keyword_name(tok.clone()));
                        if (ident_or_keyword && peek_is_colon_after_ident(tokens.clone())) {
                            {
                                let r = parse_field_init_list(tokens.clone(), ctx);
                                if has_err(r.err.clone()) {
                                    return Rc::new(ExprResult {
                                        expr: dummy_expr.clone(),
                                        tokens: r.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: r.err.clone(),
                                    });
                                }
                                let tokens = skip_newlines(r.tokens.clone());
                                let r2 =
                                    expect(tokens.clone(), Rc::new(ExpectedToken::ExpectRBrace));
                                if has_err(r2.err.clone()) {
                                    return Rc::new(ExprResult {
                                        expr: dummy_expr.clone(),
                                        tokens: r2.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: r2.err.clone(),
                                    });
                                }
                                Rc::new(ExprResult {
                                    expr: make_expr_node(
                                        Rc::new(ExprData::ExprRecordLit { parent_enum: None }),
                                        r.fields.clone(),
                                        None,
                                        span,
                                    ),
                                    tokens: r2.tokens.clone(),
                                    ctx: r.ctx.clone(),
                                    err: None,
                                })
                            }
                        } else {
                            if (tok_is_lit_str(tok.clone())
                                && peek_is_colon_after_ident(tokens.clone()))
                            {
                                {
                                    let r = parse_field_init_list(tokens.clone(), ctx);
                                    if has_err(r.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r.err.clone(),
                                        });
                                    }
                                    let tokens = skip_newlines(r.tokens.clone());
                                    let r2 = expect(
                                        tokens.clone(),
                                        Rc::new(ExpectedToken::ExpectRBrace),
                                    );
                                    if has_err(r2.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r2.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r2.err.clone(),
                                        });
                                    }
                                    Rc::new(ExprResult {
                                        expr: make_expr_node(
                                            Rc::new(ExprData::ExprRecordLit { parent_enum: None }),
                                            r.fields.clone(),
                                            None,
                                            span,
                                        ),
                                        tokens: r2.tokens.clone(),
                                        ctx: r.ctx.clone(),
                                        err: None,
                                    })
                                }
                            } else {
                                {
                                    let r = parse_stmts(tokens.clone(), ctx);
                                    if has_err(r.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r.err.clone(),
                                        });
                                    }
                                    let tokens = skip_newlines(r.tokens.clone());
                                    let r2 = expect(
                                        tokens.clone(),
                                        Rc::new(ExpectedToken::ExpectRBrace),
                                    );
                                    if has_err(r2.err.clone()) {
                                        return Rc::new(ExprResult {
                                            expr: dummy_expr.clone(),
                                            tokens: r2.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: r2.err.clone(),
                                        });
                                    }
                                    if ((r.stmts.clone().len() as i64) == 1) {
                                        Rc::new(ExprResult {
                                            expr: r.stmts.clone().first().cloned().clone().unwrap(),
                                            tokens: r2.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: None,
                                        })
                                    } else {
                                        Rc::new(ExprResult {
                                            expr: make_expr_node(
                                                Rc::new(ExprData::ExprBlock),
                                                r.stmts.clone(),
                                                None,
                                                span,
                                            ),
                                            tokens: r2.tokens.clone(),
                                            ctx: r.ctx.clone(),
                                            err: None,
                                        })
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn peek_is_colon_after_ident(tokens: Rc<TokenStream>) -> bool {
    match token_stream_first(token_stream_advance(tokens, 1)) {
        Some(t) => is_colon_shape(t.shape.clone()),
        None => false,
    }
}

